  "name": "hci_tx_queue_drain",
  "confidence": "medium",
  "docstring": "Drains queued Bluetooth HCI TX packets under IRQ/reentrancy guards, sending them via hci_tx_packet and rescheduling a wake-up when the current queued item's timestamp lies in the future.",
  "subsystem": "bt",
  "var_renames": {
    "v1": "active_count",
    "v2": "irq_disabled_flag",
    "v3": "timer_base",
    "v4": "event_lock_obj",
    "v5": "packet_timestamp",
    "v7": "tx_packet",
    "v12": "queued_packet"
  },
  "struct_hints": [
    {
      "offset": 20,
      "meaning": "control-block field holding the next queued packet/timestamped item"
    },
    {
      "offset": 32,
      "meaning": "event lock object used with ke_event_lock"
    },
    {
      "offset": 8,
      "meaning": "timestamp/due tick field of the queued packet/timestamped item"
    }
  ]
}
